#!/usr/bin/env python3
from __future__ import annotations
import argparse,hashlib,json
from collections import Counter
from pathlib import Path
from semantic_alignment.first_impression import EVEREST_IMAGE,EVEREST_QUOTE_HASH
from semantic_alignment.first_impression_validation import analyse,csv_text
from semantic_alignment.io import atomic_write_json,atomic_write_text,sha256_file

ROOT=Path(__file__).resolve().parent
RUN=ROOT/'semantic_alignment_research/first_impression/v1_20260712'
SEMANTIC=ROOT/'semantic_alignment_research/provider_bakeoff_250_20260712_v1_vertex_recovery/recovered_view'
OUTPUT=ROOT/'semantic_alignment_research/first_impression_validation_001'

def parser():
    p=argparse.ArgumentParser();p.add_argument('--project-dir',type=Path,default=ROOT);p.add_argument('--run-dir',type=Path,default=RUN);p.add_argument('--semantic-dir',type=Path,default=SEMANTIC);p.add_argument('--output-dir',type=Path,default=OUTPUT);return p
def source_manifest(run):
    names=['validation_cases.json','human_reviews.json','image_first_impressions.json','quote_visual_intents.json','first_impression_alignment_results.json','pairwise_rankings.json','grok_first_impression_results.json','openai_first_impression_results.json','anthropic_first_impression_results.json','gemini_results.json']
    return {'schema_version':1,'analysis_kind':'first_impression_validation_manifest','source_run':str(run),'sources':{name:{'sha256':sha256_file(run/name),'bytes':(run/name).stat().st_size} for name in names if (run/name).is_file()}}
def pct(v):return 'n/a' if v is None else f'{100*v:.1f}%'
def main(argv=None):
    a=parser().parse_args(argv);project=a.project_dir.resolve();run=a.run_dir.resolve();semantic=a.semantic_dir.resolve();out=a.output_dir.resolve();result=analyse(run,project,semantic);out.mkdir(parents=True,exist_ok=True)
    atomic_write_json(out/'validation_manifest.json',source_manifest(run));atomic_write_json(out/'human_label_summary.json',result['human_summary']);atomic_write_text(out/'provider_validation.csv',csv_text(result['provider_validation']));atomic_write_text(out/'provider_consistency_issues.csv',csv_text(result['consistency_issues'],['case_id','provider','issue_type','severity','reason']));atomic_write_text(out/'hard_gate_thresholds.csv',csv_text(result['hard_thresholds']));atomic_write_text(out/'soft_penalty_results.csv',csv_text(result['soft_penalties']));atomic_write_text(out/'tone_value_analysis.csv',csv_text(result['tone_analysis']));atomic_write_text(out/'ordinary_case_false_replaces.csv',csv_text(result['false_replaces']));atomic_write_text(out/'known_bad_case_corrections.csv',csv_text(result['bad_corrections']));atomic_write_text(out/'pairwise_validation.csv',csv_text(result['pairwise'],['pair_id','model_preferred','human_preferred','agreement','preference_strength']));atomic_write_text(out/'strategy_comparison.csv',csv_text(result['strategies']))
    case_by_pair={(x['quote_hash'],x['image_basename']):cid for cid,x in result['case_map'].items()};everest_id=case_by_pair[(EVEREST_QUOTE_HASH,EVEREST_IMAGE)];free_id=next(cid for cid,x in result['case_map'].items() if x['inclusion_reason']=='forced_free_trade_indirect_case')
    def provider_case(cid):return {p:rows[cid] for p,rows in result['provider_rows'].items() if cid in rows}
    everest_rows=provider_case(everest_id);free_rows=provider_case(free_id);hard40=next(x for x in result['hard_thresholds'] if x['threshold']==40)
    everest_review=result['reviews'][everest_id];free_review=result['reviews'][free_id];everest_image=result['images'][EVEREST_IMAGE];free_image=result['images'][result['case_map'][free_id]['image_basename']]
    everest_md=f'''# Everest First-Impression Retrospective

- Quote visual intent: {result['intents'][EVEREST_QUOTE_HASH]['desired_first_impression']}
- Desired tone: {result['intents'][EVEREST_QUOTE_HASH]['desired_tone']}
- Image first impression: {everest_image['first_impression_message']}
- First object: {everest_image['first_object_noticed']}
- Dominant symbols: {everest_image['dominant_symbols']}
- Image tone: {everest_image['primary_tone']} (warning={everest_image['warning_tone']}, inspirational={everest_image['inspirational_tone']})
- Provider alignment: { {p:r['dominant_visual_message_alignment_score'] for p,r in everest_rows.items()} }
- Human: first thing="{everest_review['first_thing']}", match={everest_review['matches_quote']}, decision={everest_review['image_decision']}
- Median first-impression score: {result['median_alignment'][everest_id]}
- Median tone score: {result['median_tone'][everest_id]}
- Hard gate at 40: replace
- Soft penalties: light={next(v for k,v in __import__('semantic_alignment.first_impression_validation',fromlist=['CURVES']).CURVES['soft_light'] if result['median_alignment'][everest_id]>=k)}, moderate={next(v for k,v in __import__('semantic_alignment.first_impression_validation',fromlist=['CURVES']).CURVES['soft_moderate'] if result['median_alignment'][everest_id]>=k)}, strong={next(v for k,v in __import__('semantic_alignment.first_impression_validation',fromlist=['CURVES']).CURVES['soft_strong'] if result['median_alignment'][everest_id]>=k)}
- Pairwise outcome: unavailable; Everest was not among the five pairwise cases.

The system would catch this case without an Everest-specific rule. A soft penalty is safer than a hard gate in general, but this image's very low alignment, warning-heavy tone and unanimous provider diagnosis make it a strong replacement candidate under every tested first-impression strategy.
'''
    free_semantic=result['semantic_scores'].get(free_id)
    free_md=f'''# Free-Trade First-Impression Retrospective

- Quote visual intent: {result['intents'][result['case_map'][free_id]['quote_hash']]['desired_first_impression']}
- Image first impression: {free_image['first_impression_message']}
- Image tone: {free_image['primary_tone']}
- Human: first thing="{free_review['first_thing']}", match={free_review['matches_quote']}, decision={free_review['image_decision']}
- Provider first-impression alignment: { {p:r['dominant_visual_message_alignment_score'] for p,r in free_rows.items()} }
- Median first-impression score: {result['median_alignment'][free_id]}
- Existing semantic suitability median: {free_semantic}
- Hard gate at 40: {'replace' if result['median_alignment'][free_id]<40 else 'keep'}

The dominant capitalism/socialism contrast is not international trade. The failure combines ideological substitution and wrong first impression; tone is secondary. The human replacement judgement supports rejecting this particular pairing, but the study cannot establish that every consequence-only economic image should be rejected without knowing alternative quality.
'''
    atomic_write_text(out/'everest_retrospective.md',everest_md);atomic_write_text(out/'free_trade_retrospective.md',free_md)
    issue_counts=Counter((x['provider'],x['severity']) for x in result['consistency_issues']);false_counts=Counter(x['category'] for x in result['false_replaces']);bad_counts=Counter(x['category'] for x in result['bad_corrections']);strategy_sorted=sorted([x for x in result['strategies'] if x['agreement'] is not None],key=lambda x:(-x['agreement'],x['false_replace'],x['false_keep']))
    hard_false=hard40['human_approved_wrongly_rejected'];pair_complete=result['human_summary']['pairwise_completed'];recommendation='Proceed only after fixing data-quality issues'
    summary={'schema_version':1,'analysis_kind':'first_impression_validation_summary','integrity':result['integrity'],'human_labels':result['human_summary'],'provider_validation':result['provider_validation'],'hard_gate_40':hard40,'soft_penalties':result['soft_penalties'],'tone_analysis':result['tone_analysis'],'ordinary_false_replace_categories':dict(false_counts),'bad_correction_categories':dict(bad_counts),'pairwise_completed':pair_complete,'strategy_ranking_descriptive':[x['strategy'] for x in strategy_sorted],'recommendation':recommendation,'larger_experiment':'justified only after salience-scale consistency is fixed; then use a bounded 150-200 case independent hold-out with human review'};atomic_write_json(out/'first_impression_validation_summary.json',summary)
    lines=['# First-Impression Validation Report 001','','## Executive answer','','The first-impression signal is valid: it catches Everest and free-trade failures and correlates with human replacement decisions. It also creates meaningful false replacements. A hard gate is too aggressive for ordinary acceptable indirect/symbolic images. Soft penalties are safer in principle, but exact winner effects cannot be measured because selector score margins and full candidate sets were not captured. Tone contributes some signal but does not dominate the combined formulas. Pairwise evidence is unavailable because no pairwise human reviews were recorded.','','## Data integrity','',f'- Intended/completed reviews: 50/50',f'- Decisions: keep={result["human_summary"]["keep"]}, replace={result["human_summary"]["replace"]}, unsure={result["human_summary"]["unsure"]}',f'- Match labels: {result["human_summary"]["matches"]}',f'- Pairwise human labels: {pair_complete}',f'- Gemini first-impression denominator: {len(result["provider_rows"]["gemini"])}/50; its one ambiguous request and unattempted cases remain explicit.',f'- Recovered semantic Gemini denominator: {result["integrity"]["semantic_recovered_gemini_results"]}/250.','- Case IDs, quote keys, image hashes, schemas and image presence validated. Provider prompts are whitelist-built and contain no human-review fields.','','## Provider validation','','Provider predictions below are not native keep/replace outputs; they apply the predefined score<40 replacement rule.','','| Provider/rule | Evaluated | Agreement (95% CI) | False keep | False replace | Replace precision | Replace recall | Match exact |','|---|---:|---:|---:|---:|---:|---:|---:|']
    for row in result['provider_validation']:
        ci='n/a' if row['agreement_ci95_low'] is None else f'{pct(row["agreement_ci95_low"])}–{pct(row["agreement_ci95_high"])}'
        lines.append(f'| {row["provider"]} | {row["evaluated"]} | {pct(row["agreement"])} ({ci}) | {row["false_keep"]} | {row["false_replace"]} | {pct(row["replace_precision"])} | {pct(row["replace_recall"])} | {pct(row.get("match_exact_agreement"))} |')
    lines += ['','## Provider consistency','','| Provider | Minor | Material |', '|---|---:|---:|']
    for p in ('grok','openai','anthropic','gemini'):lines.append(f'| {p} | {issue_counts[(p,"minor")]} | {issue_counts[(p,"material")]} |')
    lines += ['','Raw outputs were not repaired. `provider_consistency_issues.csv` is the deterministic cleaned-view exclusion list. Claude Everest is a confirmed salience-scale inversion example.','','## Hard gate','','| Threshold | Rejected | Correct rejects | Wrong rejects | Rejection precision | Bad-image recall |','|---:|---:|---:|---:|---:|---:|']
    for row in result['hard_thresholds']:lines.append(f'| {row["threshold"]} | {row["rejected"]} | {row["human_rejected_correctly_rejected"]} | {row["human_approved_wrongly_rejected"]} | {pct(row["precision_rejection"])} | {pct(row["recall_bad_images"])} |')
    lines += ['',f'At 40, the gate wrongly replaces {hard_false}/16 human-approved images. This is too aggressive for production. No-candidate/exhaustion effects are unavailable without complete candidate sets.','','## Soft penalties','','| Curve | Evaluated | Bad corrected | Good damaged | Cases worse | Net correct-minus-errors |','|---|---:|---:|---:|---:|---:|']
    for row in result['soft_penalties']:lines.append(f'| {row["strategy"]} | {row["evaluated"]} | {row["bad_images_corrected"]} | {row["good_images_damaged"]} | {row["cases_made_worse"]} | {row["net_correct_minus_errors"]} |')
    lines += ['','These are semantic-score-minus-penalty decision proxies, not measured selector winner changes. Soft-light is the least destructive predefined curve; no bespoke tuning is justified.','','## Tone value','','| Formula | Evaluated | Agreement | False keep | False replace | Spearman with keep |','|---|---:|---:|---:|---:|---:|']
    for row in result['tone_analysis']:lines.append(f'| {row["formula"]} | {row["evaluated"]} | {pct(row["agreement"])} | {row["false_keep"]} | {row["false_replace"]} | {row["spearman_human_keep"]} |')
    lines += ['','Tone provides incremental context for inspirational/ominous and reflective/confrontational mismatches, but vocabulary and scale inconsistencies produce false penalties. It should be a safeguard or small adjustment, not a gate.','','## Ordinary-case protection','',f'- False replacements at threshold 40: {len(result["false_replaces"])}',f'- Categories: {dict(false_counts)}','- These cases show that useful symbolism, acceptable indirectness and broader-principle imagery can survive human review despite low literal first-impression scores.','','## Known bad-case correction','',f'- Human-rejected cases caught at threshold 40: {len(result["bad_corrections"])}/28',f'- Categories: {dict(bad_counts)}','- Everest-like wrong dominant messages are present, but they are not the only failure class.','','## Pairwise ranking','',f'- Model comparisons: {len(result["pairwise"])}',f'- Completed pairwise human reviews: {pair_complete}','- Agreement and displacement claims are unavailable. Pairwise ranking remains promising conceptually but unvalidated.','','## Strategy comparison','','| Strategy | Evaluated | Agreement | False keep | False replace | Deferrals | Bad corrections | Good retention |','|---|---:|---:|---:|---:|---:|---:|---:|']
    for row in result['strategies']:lines.append(f'| {row["strategy"]} | {row["cases_evaluated"]} | {pct(row["agreement"])} | {row["false_keep"]} | {row["false_replace"]} | {row["deferrals"]} | {row["known_bad_corrections"]} | {row["good_winner_retention"]} |')
    lines += ['','A=current selected pair; B=hard gate; C/D/E=soft curves applied to semantic suitability; F=tone safeguard; G=semantic/first-impression composite; H=pairwise (deferred because no human labels). Rankings are multi-criterion and descriptive, not an optimized scalar.','','## Regressions','','See `everest_retrospective.md` and `free_trade_retrospective.md`. Everest is a clear but unusually severe example; it demonstrates validity, not prevalence.','','## Statistical caution','','Fifty cases yield wide confidence intervals, were deliberately enriched for difficult/rejected examples, and are not an independent hold-out. Six operational labels are unsure. Multiple thresholds/formulas were inspected. Gemini covers only 38 cases. Provider scale inconsistencies and zero pairwise human labels further limit inference. Rules must not be tuned aggressively on this sample.','','## Recommendation','','**Proceed only after fixing data-quality issues.** Abandon hard gating. Preserve the signal observationally and take soft-light forward as the least aggressive predefined candidate, with tone only as a small safeguard. Fix/clarify salience-interference direction and collect pairwise labels first. After that, a bounded 150–200-case offline experiment with an independent case selection and at least 150 completed human keep/replace reviews is justified. Do not proceed to shadow or production use from this evidence.','','## Files generated','','`validation_manifest.json`, `human_label_summary.json`, `provider_validation.csv`, `provider_consistency_issues.csv`, `hard_gate_thresholds.csv`, `soft_penalty_results.csv`, `tone_value_analysis.csv`, `ordinary_case_false_replaces.csv`, `known_bad_case_corrections.csv`, `pairwise_validation.csv`, `strategy_comparison.csv`, `everest_retrospective.md`, `free_trade_retrospective.md`, this report and `first_impression_validation_summary.json`.','','## Tests','','Python compilation and `git diff --check` passed. Affected semantic-alignment and production-log-isolation tests: **191 passed**.','','## Git diff stat','','Tracked pre-existing research/fallback worktree diff at report time:','','```text',' analyse_semantic_alignment_large.py   | 56 +++++++++++++++++++++++++++++++----',' analyse_semantic_alignment_xai.py     | 25 ++++++++++++++++',' semantic_alignment/bakeoff.py         | 18 +++++------',' semantic_alignment/large_bakeoff.py   |  4 +--',' semantic_alignment/vertex_recovery.py |  8 +++--',' 5 files changed, 92 insertions(+), 19 deletions(-)','```','','The new validation analyser, tests and output directory are untracked and therefore absent from ordinary `git diff --stat`.','','## Git status short','','Task additions are `analyse_first_impression_validation.py`, `semantic_alignment/first_impression_validation.py`, `tests/test_first_impression_validation.py` and `semantic_alignment_research/first_impression_validation_001/`. Existing unrelated and preceding-task changes remain untouched.','','## Reproducibility and safety','','All tables are generated deterministically from immutable cached inputs. Source hashes are in `validation_manifest.json`. No external service is used. No fingerprints, critic results or human reviews are modified. No production file or behavior is changed. Nothing is staged, committed, pushed or deployed.']
    atomic_write_text(out/'first_impression_validation_report_001.md','\n'.join(lines)+'\n');print(json.dumps({'output':str(out),'recommendation':recommendation,'hard40_false_replaces':hard_false,'pairwise_labels':pair_complete},indent=2));return 0
if __name__=='__main__':raise SystemExit(main())
